 select e.id lexical_entry_id,e.strong_number,e.source_gloss,map.display_gloss_es,
        regexp_replace(split_part(e.source_gloss,'»',1),'^:\s*','') primary_en
 from public.biblical_lexical_entries e
 join map on map.primary_en=regexp_replace(split_part(e.source_gloss,'»',1),'^:\s*','')
 left join public.biblical_hebrew_spanish_glosses g on g.lexical_entry_id=e.id
 where e.language='hebrew' and e.enabled and e.review_status='approved' and e.part_of_speech='noun'
   and e.source_gloss like ':%' and e.display_gloss_es is null and g.lexical_entry_id is null
)
