 jsonb_build_object('phase','FASE_H_BLOQUE_3','batch_id','fase_h_es_nouns_structured_001_20260820','source','STEPBible/TAHOT structured source_gloss en','source_license','CC BY 4.0','translation_layer','VIDA editorial Spanish','translation_basis','explicit primary sense before »; noun POS','context_used_as_meaning',false,'rv1909_used_as_meaning',false,'hebrew_lemma_used_to_infer_meaning',false,'strong_number',strong_number,'primary_sense_en',primary_en)
from eligible
